head.b:skin:
/* ===== Magazine Theme for Blogger (original design) ===== */
:root{--accent:#ff2232;--bg:#f4f5f7;--card:#fff;--text:#1d2129;--muted:#6b7280;--line:#e5e7eb;--radius:6px;--max:1180px}
body.dark{--bg:#0f1115;--card:#181b22;--text:#e8eaed;--muted:#9aa0aa;--line:#272b34}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Poppins',Arial,sans-serif;background:var(--bg);color:var(--text);font-size:15px;line-height:1.7;-webkit-text-size-adjust:100%;text-size-adjust:100%}
a{color:inherit;text-decoration:none}a:hover{color:var(--accent)}
img{max-width:100%;height:auto;display:block}
ul{list-style:none}
.wrap{max-width:var(--max);margin:0 auto;padding:0 16px}
/* top bar + nav */
#topbar{background:#111;color:#fff;font-size:13px}
#topbar .wrap{display:flex;justify-content:space-between;align-items:center;min-height:38px}
#topbar a{color:#ddd;margin-right:14px}
#topbar a:hover{color:#fff}
#theme-toggle{background:none;border:1px solid #555;color:#fff;border-radius:20px;padding:2px 12px;cursor:pointer;font:inherit;font-size:12px}
#header .wrap{display:flex;justify-content:space-between;align-items:center;gap:20px;padding-top:18px;padding-bottom:18px;flex-wrap:wrap}
#header h1,#header .site-title{font-size:30px;font-weight:700;line-height:1.1}
#header h1 a span{color:var(--accent)}
#header-ad{max-width:728px}
#navwrap{background:var(--card);border-top:3px solid var(--accent);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:50}
#navwrap .wrap{display:flex;align-items:center;justify-content:space-between}
#menu ul{display:flex;flex-wrap:wrap}
#menu li{position:relative}
#menu a{display:block;padding:14px 16px;font-weight:600;font-size:14px;text-transform:uppercase;letter-spacing:.3px}
#menu li.has-sub>a:after{content:' \25BE';font-size:10px}
#menu .sub{display:none;position:absolute;left:0;top:100%;background:var(--card);min-width:200px;border:1px solid var(--line);box-shadow:0 8px 20px rgba(0,0,0,.1);flex-direction:column}
#menu li:hover>.sub{display:flex}
#menu .sub a{text-transform:none;font-weight:500;padding:10px 16px;border-bottom:1px solid var(--line)}
#search-form{display:flex}
#search-form input{border:1px solid var(--line);background:var(--bg);color:var(--text);padding:7px 12px;border-radius:20px 0 0 20px;outline:none;width:160px;font:inherit;font-size:13px}
#search-form button{border:0;background:var(--accent);color:#fff;padding:0 14px;border-radius:0 20px 20px 0;cursor:pointer}
#menu-btn{display:none;background:none;border:0;font-size:24px;cursor:pointer;color:var(--text)}
/* layout */
#content{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:28px;margin:26px auto}
#main-col,#sidebar{min-width:0}
.no-sidebar #content{grid-template-columns:minmax(0,1fr)}
.sec-title{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid var(--line);margin:0 0 16px;position:relative}
.sec-title h1,.sec-title h2,.sec-title h3{font-size:16px;text-transform:uppercase;font-weight:700;background:var(--accent);color:#fff;padding:5px 14px;margin-bottom:-2px}
.sec-title a{font-size:12px;color:var(--muted)}
.block{margin-bottom:30px}
.card{background:var(--card);border-radius:var(--radius);overflow:hidden;border:1px solid var(--line)}
.thumb{display:block;aspect-ratio:16/9;background:linear-gradient(135deg,#ff2232,#6a11cb);background-size:cover;background-position:center}
.card .info{padding:12px 14px}
.card h3,.card h2{font-size:15px;line-height:1.4;font-weight:600}
.meta{font-size:12px;color:var(--muted);margin-top:4px}
.tag{display:inline-block;background:var(--accent);color:#fff;font-size:11px;padding:1px 9px;border-radius:3px;text-transform:uppercase;margin-bottom:6px}
/* minmax(0,...) stops long titles or wide content from stretching a grid past the screen */
.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
/* hero */
.hero{display:grid;grid-template-columns:1.4fr 1fr 1fr;grid-template-rows:1fr 1fr;gap:6px;margin-bottom:30px;height:430px}
.hero .h{position:relative;background-size:cover;background-position:center;background-color:#222;border-radius:var(--radius);overflow:hidden;color:#fff}
.hero .h:first-child{grid-row:1/3}
.hero .h:after{content:'';position:absolute;inset:0;background:linear-gradient(transparent 35%,rgba(0,0,0,.85))}
.hero .h .t{position:absolute;left:0;right:0;bottom:0;padding:14px;z-index:2}
.hero .h h3{font-size:15px;line-height:1.35;color:#fff}
.hero .h:first-child h3{font-size:24px}
.hero .h a.full{position:absolute;inset:0;z-index:3}
/* list rows */
.row{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}
.row:last-child{border:0}
.row .thumb{width:90px;min-width:90px;aspect-ratio:1/1;border-radius:4px}
.row h3{font-size:14px;line-height:1.4;font-weight:600}
/* posts */
.post-card{display:grid;grid-template-columns:260px minmax(0,1fr);gap:18px;margin-bottom:18px;background:var(--card);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}
.post-card .thumb{height:100%;aspect-ratio:auto;min-height:170px}
.post-card .info{padding:16px 16px 16px 0}
.post-card h2{font-size:20px;line-height:1.35}
.post-card p{color:var(--muted);margin-top:8px;font-size:14px}
.pager{display:flex;justify-content:space-between;margin:20px 0}
.pager a{background:var(--accent);color:#fff;padding:8px 18px;border-radius:4px;font-weight:600}
/* single post */
.post-single{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:26px}
.post-single h1{font-size:32px;line-height:1.3;margin:6px 0 10px}
.post-body{margin-top:20px;font-size:16.5px;line-height:1.85;overflow-wrap:break-word;word-wrap:break-word}
.post-body h2,.post-body h3{margin:24px 0 10px;line-height:1.35}
.post-body p{margin-bottom:16px}
.post-body ul,.post-body ol{margin:0 0 16px 22px;list-style:revert}
.post-body a{color:var(--accent)}
.post-body table{border-collapse:collapse;width:100%;margin-bottom:16px}
.post-body td,.post-body th{border:1px solid var(--line);padding:8px}
.post-body iframe,.post-body video,.post-body embed,.post-body object{max-width:100%}
.post-body pre{max-width:100%;overflow-x:auto}
/* tables in posts are wrapped in this by the script at the bottom so they scroll sideways on phones */
.table-scroll{width:100%;overflow-x:auto;margin:0 0 16px}
.table-scroll>table{margin:0!important}
.share{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}
.share a{background:var(--accent);color:#fff;padding:6px 14px;border-radius:4px;font-size:13px}
.share a.wa{background:#25d366}.share a.fb{background:#1877f2}.share a.tw{background:#111}
#related{margin-top:26px}
.comments{margin-top:26px}
/* sidebar */
.widget{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:16px;margin-bottom:22px}
.widget>h3{font-size:15px;text-transform:uppercase;border-bottom:2px solid var(--accent);padding-bottom:6px;margin-bottom:12px}
.widget li a{display:block;padding:6px 0;border-bottom:1px solid var(--line)}
.cloud{display:flex;flex-wrap:wrap;gap:6px}
.cloud a{border:1px solid var(--line);padding:2px 12px;border-radius:20px;font-size:13px}
.cloud a:hover{background:var(--accent);color:#fff;border-color:var(--accent)}
/* footer */
#footer{background:#111;color:#bbb;margin-top:30px;padding:34px 0 18px}
#footer h3{color:#fff;margin-bottom:10px}
#footer a:hover{color:#fff}
.foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:30px}
.copy{border-top:1px solid #2a2a2a;margin-top:24px;padding-top:14px;font-size:13px;text-align:center}
.ad-slot{text-align:center;margin:0 0 24px}
.widget .widget{border:0;padding:0;margin:0;background:none}

/* accessibility + footer */
.skip{position:absolute;left:-9999px;top:0;background:#fff;color:#000;padding:10px 16px;z-index:9999;font-weight:600}
.skip:focus{left:8px;top:8px}
a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #ffb703;outline-offset:2px}
#menu li:focus-within>.sub{display:flex}
#footer ul{list-style:none}#footer li a{display:inline-block;padding:4px 0}
#footer p{margin-bottom:8px}
#footer a{text-decoration:underline;text-underline-offset:3px}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
#topbar .widget,#header .widget,#navwrap .widget,#footer .widget{background:none;border:0;padding:0;margin:0;border-radius:0}
#footer .copy .widget{display:inline;color:#bbb}

/* blessings, duas and copy buttons */
.post-body .blessings{list-style:none;margin:0 0 22px;padding:0}
.post-body .blessings li{position:relative;background:var(--bg);border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:6px;padding:12px 108px 12px 14px;margin:0 0 10px;line-height:1.7}
.copy-btn{display:inline-flex;align-items:center;gap:6px;background:var(--card);color:var(--text);border:1px solid var(--line);border-radius:20px;padding:4px 11px;font:inherit;font-size:12px;cursor:pointer;line-height:1.4}
.copy-btn:hover{border-color:var(--accent);color:var(--accent)}
.copy-btn.done{background:var(--accent);border-color:var(--accent);color:#fff}
.blessings li .copy-btn{position:absolute;right:10px;top:50%;transform:translateY(-50%)}
.post-body .dua{position:relative;background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:18px 18px 14px;margin:0 0 22px}
.post-body .dua .copy-btn{position:absolute;right:10px;top:10px}
.post-body .dua .ar{font-family:'Amiri','Noto Naskh Arabic',serif;font-size:28px;line-height:2;direction:rtl;text-align:right;margin:26px 0 8px;color:var(--text)}
.post-body .dua .tr{font-style:italic;color:var(--muted);margin:0 0 6px}
.post-body .dua .mn{margin:0 0 6px}
.post-body .dua .src{font-size:13px;color:var(--muted);margin:0}
.post-body .note{background:var(--bg);border-left:4px solid var(--accent);padding:12px 16px;border-radius:6px;margin:0 0 18px}
.post-body h3{font-size:19px;margin:20px 0 8px}
.post-body .faq h3{font-size:17px}
@media(max-width:640px){.post-body .blessings li{padding:12px 14px 54px}.blessings li .copy-btn{top:auto;bottom:10px;transform:none;right:10px}.post-body .dua .ar{font-size:24px}}

html{scroll-behavior:smooth}
.crumbs{margin:0 0 14px;font-size:13px;color:var(--muted)}
.crumbs ol{display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;list-style:none;margin:0;padding:0}
.crumbs li{display:inline-flex;align-items:center;min-width:0}
.crumbs li+li::before{content:"\203A";margin-right:6px;opacity:.55}
.crumbs a{color:var(--muted)} .crumbs a:hover{color:var(--accent)}
.crumbs [aria-current]{color:var(--text);font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:46ch}
.post-body h2,.post-body h3{scroll-margin-top:74px}
#toc-btn{position:fixed;left:0;top:40%;z-index:60;writing-mode:vertical-rl;transform:rotate(180deg);background:var(--accent);color:#fff;border:0;padding:14px 8px;border-radius:0 8px 8px 0;font:600 12px Poppins,Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;box-shadow:0 2px 10px rgba(0,0,0,.2)}
#toc-btn:hover{filter:brightness(1.08)}
#toc-panel{position:fixed;left:0;top:64px;bottom:18px;width:310px;max-width:88vw;background:var(--card);color:var(--text);border:1px solid var(--line);border-left:0;border-radius:0 10px 10px 0;box-shadow:0 10px 34px rgba(0,0,0,.22);transform:translateX(-106%);transition:transform .26s ease;z-index:70;display:flex;flex-direction:column;visibility:hidden}
#toc-panel.open{transform:none;visibility:visible}
#toc-panel .toc-h{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line);font-weight:700;font-size:14px}
#toc-panel .toc-x{background:none;border:0;color:var(--muted);font-size:22px;line-height:1;cursor:pointer;padding:0 4px}
#toc-panel .toc-x:hover{color:var(--accent)}
#toc-list{list-style:none;margin:0;padding:10px 8px 14px;overflow-y:auto;flex:1}
#toc-list li{margin:0}
#toc-list a{display:block;padding:7px 10px;border-radius:6px;font-size:13.5px;line-height:1.4;color:var(--text);border-left:3px solid transparent}
#toc-list li.l3 a{padding-left:24px;font-size:13px;color:var(--muted)}
#toc-list a:hover{background:rgba(127,127,127,.12);color:var(--accent)}
#toc-list a.on{border-left-color:var(--accent);background:rgba(255,34,50,.08);color:var(--accent);font-weight:600}
@media(max-width:900px){#toc-btn{writing-mode:horizontal-tb;transform:none;left:12px;top:auto;bottom:14px;border-radius:22px;padding:10px 16px}#toc-panel{top:auto;bottom:0;left:0;width:100%;max-width:100%;max-height:68vh;border:0;border-top:1px solid var(--line);border-radius:14px 14px 0 0;transform:translateY(105%)}#toc-panel.open{transform:none}}
@media print{#toc-btn,#toc-panel{display:none!important}}

/* =====================================================
   RESPONSIVE LAYER
   Desktop (901px+) is unchanged. Everything below only
   applies on tablets and phones.
   ===================================================== */

/* Tablets: single column, hamburger menu */
@media(max-width:900px){
  #content{grid-template-columns:minmax(0,1fr);margin:20px auto}
  .grid4,.grid3{grid-template-columns:repeat(2,minmax(0,1fr))}
  .hero{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:auto;height:auto}
  .hero .h{min-height:200px}
  .hero .h:first-child{grid-column:1/3;grid-row:auto;min-height:280px}
  /* header: keep wide ads inside the screen */
  #header .section{min-width:0;max-width:100%}
  #header-ad{max-width:100%;overflow-x:auto}
  /* nav: hamburger on the left, search on the right, menu drops below */
  #navwrap .wrap{flex-wrap:wrap;gap:0 12px;min-height:50px}
  #menu-btn{display:flex;align-items:center;justify-content:center;width:44px;height:44px;margin-left:-10px;line-height:1}
  #menu{display:none;order:3;width:100%;border-top:1px solid var(--line)}
  #menu.open{display:block}
  #menu ul{flex-direction:column;flex-wrap:nowrap}
  #menu li{border-bottom:1px solid var(--line)}
  #menu li:last-child{border-bottom:0}
  #menu a{padding:12px 4px;border-bottom:0}
  #menu .sub{position:static;display:flex;box-shadow:none;border:0;min-width:0;background:none;padding:0 0 6px 14px}
  #menu .sub a{border-bottom:0;padding:9px 4px}
  #search-form{margin-left:auto}
  /* 16px stops iOS from zooming in when the search box is tapped */
  #search-form input{font-size:16px;width:200px;min-width:0}
  /* remove Blogger's default section side-margins so content uses the full width */
  .section{margin-left:0;margin-right:0}
  .foot-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .foot-grid>:first-child{grid-column:1/-1}
  .post-single h1{font-size:28px}
  .post-body iframe[src*="youtube"]{width:100%;height:auto;aspect-ratio:16/9}
}

/* Phones */
@media(max-width:640px){
  #topbar{font-size:12.5px}
  #topbar .wrap{flex-wrap:wrap;gap:4px 10px;padding-top:6px;padding-bottom:6px}
  #topbar a{display:inline-block;margin-right:10px;padding:4px 0}
  #header .wrap{padding-top:12px;padding-bottom:12px;gap:10px}
  #header h1,#header .site-title{font-size:24px}
  /* search moves inside the opened menu */
  #search-form{display:none;order:4;width:100%;margin:0 0 12px}
  #navwrap.nav-open #search-form{display:flex}
  #search-form input{flex:1;width:auto}
  .hero .h{min-height:160px}
  .hero .h:first-child{min-height:230px}
  .hero .h .t{padding:10px}
  .hero .h h3{font-size:13.5px}
  .hero .h:first-child h3{font-size:19px}
  .grid3,.grid2{grid-template-columns:minmax(0,1fr)}
  .post-card{grid-template-columns:minmax(0,1fr)}
  .post-card .thumb{height:auto;min-height:0;aspect-ratio:16/9}
  .post-card .info{padding:0 14px 14px}
  .post-card h2{font-size:18px}
  .post-single{padding:16px}
  .post-single h1{font-size:25px}
  .post-body{font-size:16px}
  .crumbs [aria-current]{max-width:100%}
  .widget{padding:14px}
  .share a{padding:8px 14px}
  .foot-grid{grid-template-columns:minmax(0,1fr);gap:22px}
  /* un-float images inserted by the Blogger post editor */
  .post-body .separator a,.post-body a[style*="float"]{float:none!important;margin-left:0!important;margin-right:0!important}
  .post-body img{margin-left:auto;margin-right:auto}
}

body.script:
//
/* ---------- EDIT HERE: homepage sections (label = your Blogger label; '' = latest posts) ---------- */
var HOME_SECTIONS = [
  {type:'hero',  label:'',        title:'',         n:5},
  {type:'grid3', label:'Jobs',    title:'Jobs',     n:3},
  {type:'grid4', label:'Guides',  title:'Guides',   n:4},
  {type:'list2', label:'News',    title:'News',     n:6}
];
/* ------------------------------------------------------------------------------------------------ */
(function(){
  var d=document,$=function(s,c){return (c||d).querySelector(s)};
  // dark mode
  try{if(localStorage.getItem('dark')==='1')d.body.classList.add('dark')}catch(e){}
  $('#theme-toggle').onclick=function(){d.body.classList.toggle('dark');try{localStorage.setItem('dark',d.body.classList.contains('dark')?'1':'0')}catch(e){}};
  // mobile menu (also reveals the search box on phones)
  var mb=$('#menu-btn'),mn=$('#menu'),nw=$('#navwrap');
  function setMenu(o){mn.classList.toggle('open',o);nw.classList.toggle('nav-open',o);mb.setAttribute('aria-expanded',o?'true':'false')}
  mb.onclick=function(){setMenu(!mn.classList.contains('open'))};
  d.addEventListener('keydown',function(e){if(e.key==='Escape'&&mn.classList.contains('open')){setMenu(false);mb.focus()}});
  // dropdown: link names starting with "_" become sub-items of the previous item
  var ul=$('#menu ul');
  if(ul){var last=null;[].slice.call(ul.children).forEach(function(li){
    var a=li.querySelector('a'),t=a.textContent.trim();
    if(t.charAt(0)==='_'){a.textContent=t.replace(/^_+/,'');
      if(last){var s=last.querySelector('.sub');if(!s){s=d.createElement('div');s.className='sub';last.appendChild(s);last.classList.add('has-sub')}
        s.appendChild(a);li.parentNode.removeChild(li)}}
    else last=li;});}
  // reading time
  var pb=$('#post-body'),rt=$('#readtime');
  if(pb&&rt){rt.textContent=Math.max(1,Math.round(pb.textContent.split(/\s+/).length/200))+' min read'}
  // feed helper
  function feed(label,n,cb){
    var u='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+n;
    fetch(u).then(function(r){return r.json()}).then(function(j){
      var out=(j.feed.entry||[]).map(function(e){
        var link='';(e.link||[]).forEach(function(l){if(l.rel==='alternate')link=l.href});
        var img=e.media$thumbnail?e.media$thumbnail.url.replace(/\/s\d+(-c)?\//,'/w800-h450-c/'):'';
        if(!img){var m=(e.content&&e.content.$t||'').match(/<img[^>]+src="([^"]+)"/);if(m)img=m[1]}
        return {t:e.title.$t,u:link,i:img,d:new Date(e.published.$t).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}),c:(e.category&&e.category[0])?e.category[0].term:''};
      });cb(out)}).catch(function(){cb([])});
  }
  function bg(i){return i?' style="background-image:url('+i+')"':''}
  function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;')}
  function head(t,l){return '<div class="sec-title"><h2>'+esc(t)+'</h2>'+(l?'<a href="/search/label/'+encodeURIComponent(l)+'">View all</a>':'')+'</div>'}
  function card(p){return '<div class="card"><a class="thumb" href="'+p.u+'"'+bg(p.i)+'></a><div class="info"><h3><a href="'+p.u+'">'+esc(p.t)+'</a></h3><div class="meta">'+p.d+'</div></div></div>'}
  function rowh(p){return '<div class="row"><a class="thumb" href="'+p.u+'"'+bg(p.i)+'></a><div><h3><a href="'+p.u+'">'+esc(p.t)+'</a></h3><div class="meta">'+p.d+'</div></div></div>'}
  // homepage blocks (only on the front page)
  var box=$('#home-blocks');
  if(box&&d.body.classList.contains('home')&&!/\/search|[?&]q=/.test(location.href)){
    HOME_SECTIONS.forEach(function(s){
      var el=d.createElement('section');el.className='block';box.appendChild(el);
      feed(s.label,s.n,function(ps){
        if(!ps.length){el.remove();return}
        var h='';
        if(s.type==='hero'){h='<div class="hero">'+ps.map(function(p){return '<div class="h"'+bg(p.i)+'><a class="full" href="'+p.u+'"></a><div class="t">'+(p.c?'<span class="tag">'+esc(p.c)+'</span>':'')+'<h3>'+esc(p.t)+'</h3></div></div>'}).join('')+'</div>';el.className='';}
        else if(s.type==='grid3'){h=head(s.title,s.label)+'<div class="grid3">'+ps.map(card).join('')+'</div>'}
        else if(s.type==='grid4'){h=head(s.title,s.label)+'<div class="grid4">'+ps.map(card).join('')+'</div>'}
        else{h=head(s.title,s.label)+'<div class="grid2"><div>'+ps.slice(0,Math.ceil(ps.length/2)).map(rowh).join('')+'</div><div>'+ps.slice(Math.ceil(ps.length/2)).map(rowh).join('')+'</div></div>'}
        el.innerHTML=h;
      });
    });
  }
  // related posts
  var rel=$('#related');
  var fl=$('.post-single .cloud a');if(rel&&fl){feed(fl.textContent.trim(),5,function(ps){
    var cur=rel.getAttribute('data-url');ps=ps.filter(function(p){return p.u!==cur}).slice(0,4);
    if(ps.length)rel.innerHTML=head('Related Posts')+'<div class="grid4">'+ps.map(card).join('')+'</div>'});}
})();

/* copy buttons for blessings and duas */
(function(){
  var d=document;
  // wrap post tables so they scroll sideways on small screens
  [].forEach.call(d.querySelectorAll('.post-body table'),function(t){
    if(t.parentNode.classList&&t.parentNode.classList.contains('table-scroll'))return;
    var w=d.createElement('div');w.className='table-scroll';t.parentNode.insertBefore(w,t);w.appendChild(t);
  });
  var ico='<svg viewBox="0 0 24 24" width="15" height="15" aria-hidden="true" focusable="false"><path fill="currentColor" d="M16 1H4a2 2 0 0 0-2 2v14h2V3h12V1zm3 4H8a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h11a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2zm0 16H8V7h11v14z"/></svg>';
  function copyText(t){
    if(navigator.clipboard&&window.isSecureContext){return navigator.clipboard.writeText(t)}
    return new Promise(function(res,rej){var ta=d.createElement('textarea');ta.value=t;ta.setAttribute('readonly','');ta.style.cssText='position:fixed;opacity:0;top:0';d.body.appendChild(ta);ta.select();var ok=false;try{ok=d.execCommand('copy')}catch(e){}d.body.removeChild(ta);ok?res():rej()});
  }
  function attach(el,label,getText){
    var txt=getText(el);
    var b=d.createElement('button');b.type='button';b.className='copy-btn';b.setAttribute('aria-label',label);b.innerHTML=ico+'<span>Copy</span>';
    b.onclick=function(){copyText(txt).then(function(){b.classList.add('done');b.lastChild.textContent='Copied';setTimeout(function(){b.classList.remove('done');b.lastChild.textContent='Copy'},1800)}).catch(function(){b.lastChild.textContent='Press Ctrl+C'})};
    el.appendChild(b);
  }
  [].forEach.call(d.querySelectorAll('.post-body .blessings li'),function(li){attach(li,'Copy this blessing',function(e){return e.textContent.replace(/\s+/g,' ').trim()})});
  [].forEach.call(d.querySelectorAll('.post-body .dua'),function(du){attach(du,'Copy this dua',function(e){return [].map.call(e.querySelectorAll('.ar,.tr,.mn'),function(p){return p.textContent.trim()}).join('\n')})});
})();
