(function(){
var d=document,nav=d.getElementById('crumbs');
function origin(){var c=d.querySelector('link[rel=canonical]');try{return c?new URL(c.href).origin:location.origin}catch(e){return location.origin}}
if(nav){
 var post=d.querySelector('.post-single');
 var tags=[].slice.call(d.querySelectorAll('.post-single a[rel=tag]')).map(function(a){return a.textContent.trim()});
 if(post&&tags.length){
  var pri=['Daily Blessings','Occasion Blessings','Islamic Quotes','Duas','Blessings'],pick=tags[0];
  for(var i=0;i<pri.length;i++){if(tags.indexOf(pri[i])>-1){pick=pri[i];break}}
  var li=d.createElement('li'),a=d.createElement('a');
  a.href='/search/label/'+encodeURIComponent(pick);a.textContent=pick;li.appendChild(a);
  var t=nav.querySelector('.bc-title');if(t)t.parentNode.insertBefore(li,t);
 }
 var items=[].slice.call(nav.querySelectorAll('li')),o=origin(),list=[];
 items.forEach(function(el,k){var a=el.querySelector('a'),s=el.querySelector('span');
  var item={'@type':'ListItem','position':k+1,'name':(a||s).textContent.trim()};
  if(a){item.item=new URL(a.getAttribute('href'),o+'/').href}else{item.item=location.origin+location.pathname}
  list.push(item)});
 var sc=d.createElement('script');sc.type='application/ld+json';
 sc.text=JSON.stringify({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':list});
 d.head.appendChild(sc);
}
var body=d.querySelector('.post-body');
if(!body||!d.body.classList.contains('inner'))return;
var hs=[].slice.call(body.querySelectorAll('h2,h3')).filter(function(h){return h.textContent.trim()&&!(h.tagName==='H3'&&h.closest('.faq'))});
if(hs.length<3)return;
var used={};
function slug(s){var x=s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,60)||'section';var b=x,n=2;while(used[x]||(d.getElementById(x)&&d.getElementById(x).tagName.indexOf('H')!==0)){x=b+'-'+n++}used[x]=1;return x}
var btn=d.createElement('button');btn.id='toc-btn';btn.type='button';btn.setAttribute('aria-expanded','false');btn.setAttribute('aria-controls','toc-panel');btn.textContent='Contents';
var pan=d.createElement('div');pan.id='toc-panel';pan.setAttribute('role','navigation');pan.setAttribute('aria-label','Table of contents');
pan.innerHTML='<div class="toc-h"><span>In this article</span><button type="button" class="toc-x" aria-label="Close contents">&times;</button></div><ol id="toc-list"></ol>';
d.body.appendChild(btn);d.body.appendChild(pan);
var ul=pan.querySelector('#toc-list'),links=[];
hs.forEach(function(h){if(!h.id)h.id=slug(h.textContent);else used[h.id]=1;
 var li=d.createElement('li');li.className=h.tagName==='H3'?'l3':'l2';
 var a=d.createElement('a');a.href='#'+h.id;a.textContent=h.textContent.trim();li.appendChild(a);ul.appendChild(li);links.push({a:a,h:h})});
function set(o){pan.classList.toggle('open',o);btn.setAttribute('aria-expanded',o?'true':'false')}
btn.addEventListener('click',function(e){e.stopPropagation();set(!pan.classList.contains('open'))});
pan.querySelector('.toc-x').addEventListener('click',function(){set(false)});
d.addEventListener('keydown',function(e){if(e.key==='Escape')set(false)});
d.addEventListener('click',function(e){if(pan.classList.contains('open')&&!pan.contains(e.target)&&e.target!==btn)set(false)});
ul.addEventListener('click',function(e){if(window.innerWidth<=900&&e.target.tagName==='A')set(false)});
if('IntersectionObserver' in window){
 var io=new IntersectionObserver(function(es){es.forEach(function(en){if(en.isIntersecting){links.forEach(function(l){l.a.classList.toggle('on',l.h===en.target)})}})},{rootMargin:'-80px 0px -70% 0px'});
 links.forEach(function(l){io.observe(l.h)});
}
})();
